const std = @import("std");
const mem = std.mem;

pub fn encode(allocator: mem.Allocator, msg: []const u8, rails: u3) mem.Allocator.Error![]u8 {
    if (rails == 1) {
        return allocator.dupe(u8, msg);
    }

    const rail_count = rails;
    var rail_buffers = try allocator.alloc([]u8, rail_count);
    defer {
        for (rail_buffers) |rb| {
            allocator.free(rb);
        }
        allocator.free(rail_buffers);
    }

    for (rail_buffers) |*rb| {
        rb.* = &[_]u8{};
    }

    var current_rail: u32 = 0;
    var direction: i32 = 1;

    for (msg) |c| {
        rail_buffers[current_rail] = rail_buffers[current_rail] ++ &[_]u8{c};
        current_rail = @intCast(@as(i32, current_rail) + direction);
        if (current_rail == 0 or current_rail == rail_count - 1) {
            direction *= -1;
        }
    }

    var result = std.ArrayList(u8).init(allocator);
    try result.ensureTotalCapacity(msg.len);

    for (rail_buffers) |rb| {
        result.appendSlice(rb) catch unreachable;
    }

    return result.toOwnedSlice();
}
